g -->\n        <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#666\"},\"typography\":{\"fontSize\":\"0.90rem\",\"lineHeight\":\"1.7\"}}} -->\n        <p class=\"has-text-color\" style=\"color:#666;font-size:0.90rem;line-height:1.7\">Agende com total flexibilidade, no dia e horário que funciona pra você. Confirmação rápida.</p>\n        <!-- /wp:paragraph -->\n      </div>\n      <!-- /wp:column -->\n\n      <!-- wp:column {\"style\":{\"color\":{\"background\":\"#ffffff\"},\"border\":{\"radius\":\"20px\",\"top\":{\"color\":\"#2F80D3\",\"width\":\"4px\"}},\"spacing\":{\"padding\":{\"top\":\"36px\",\"bottom\":\"36px\",\"left\":\"26px\",\"right\":\"26px\"}}}} -->\n      <div class=\"wp-block-column has-background\" style=\"background-color:#ffffff;border-radius:20px;border-top-color:#2F80D3;border-top-width:4px;padding:36px 26px\">\n        <!-- wp:heading {\"level\":3,\"style\":{\"color\":{\"text\":\"#2F80D3\"},\"typography\":{\"fontSize\":\"2.6rem\",\"fontWeight\":\"900\",\"lineHeight\":\"1\"},\"spacing\":{\"margin\":{\"bottom\":\"22px\"}}}} -->\n        <h3 class=\"wp-block-heading has-text-color\" style=\"color:#2F80D3;font-size:2.6rem;font-weight:900;line-height:1;margin-bottom:22px\">03</h3>\n        <!-- /wp:heading -->\n        <!-- wp:heading {\"level\":4,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontSize\":\"1.05rem\",\"fontWeight\":\"700\"},\"spacing\":{\"margin\":{\"bottom\":\"10px\"}}}} -->\n        <h4 class=\"wp-block-heading has-text-color\" style=\"color:#1a1a2e;font-size:1.05rem;font-weight:700;margin-bottom:10px\">Realize a sessão</h4>\n        <!-- /wp:heading -->\n        <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#666\"},\"typography\":{\"fontSize\":\"0.90rem\",\"lineHeight\":\"1.7\"}}} -->\n        <p class=\"has-text-color\" style=\"color:#666;font-size:0.90rem;line-height:1.7\">100% online, link Google Meet automático. Seguro, sigiloso e no conforto da sua casa.</p>\n        <!-- /wp:paragraph -->\n      </div>\n      <!-- /wp:column -->\n\n      <!-- wp:column {\"style\":{\"color\":{\"background\":\"#ffffff\"},\"border\":{\"radius\":\"20px\",\"top\":{\"color\":\"#E03673\",\"width\":\"4px\"}},\"spacing\":{\"padding\":{\"top\":\"36px\",\"bottom\":\"36px\",\"left\":\"26px\",\"right\":\"26px\"}}}} -->\n      <div class=\"wp-block-column has-background\" style=\"background-color:#ffffff;border-radius:20px;border-top-color:#E03673;border-top-width:4px;padding:36px 26px\">\n        <!-- wp:heading {\"level\":3,\"style\":{\"color\":{\"text\":\"#E03673\"},\"typography\":{\"fontSize\":\"2.6rem\",\"fontWeight\":\"900\",\"lineHeight\":\"1\"},\"spacing\":{\"margin\":{\"bottom\":\"22px\"}}}} -->\n        <h3 class=\"wp-block-heading has-text-color\" style=\"color:#E03673;font-size:2.6rem;font-weight:900;line-height:1;margin-bottom:22px\">04</h3>\n        <!-- /wp:heading -->\n        <!-- wp:heading {\"level\":4,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontSize\":\"1.05rem\",\"fontWeight\":\"700\"},\"spacing\":{\"margin\":{\"bottom\":\"10px\"}}}} -->\n        <h4 class=\"wp-block-heading has-text-color\" style=\"color:#1a1a2e;font-size:1.05rem;font-weight:700;margin-bottom:10px\">Siga seu processo</h4>\n        <!-- /wp:heading -->\n        <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#666\"},\"typography\":{\"fontSize\":\"0.90rem\",\"lineHeight\":\"1.7\"}}} -->\n        <p class=\"has-text-color\" style=\"color:#666;font-size:0.90rem;line-height:1.7\">Prontuário, orientações e histórico completo. Acompanhamento contínuo na sua jornada.</p>\n        <!-- /wp:paragraph -->\n      </div>\n      <!-- /wp:column -->\n\n    </div>\n    <!-- /wp:columns -->\n\n  </div>\n  <!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n\n<!-- ═══════════════════════════════════════════════════════════\n     SOBRE O MEU DIVÃ\n     Foto: terapeuta homem sorrindo, sem máscara, conversa natural\n════════════════════════════════════════════════════════════ -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"white\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"96px\",\"bottom\":\"96px\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-group alignfull has-white-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:96px;padding-bottom:96px\">\n\n  <!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1100px\"}} -->\n  <div class=\"wp-block-group\">\n\n    <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"80px\"}}}} -->\n    <div class=\"wp-block-columns alignwide\">\n\n      <!-- wp:column {\"width\":\"46%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n      <div class=\"wp-block-column\" style=\"flex-basis:46%\">\n\n        <!-- wp:image {\"sizeSlug\":\"full\",\"style\":{\"border\":{\"radius\":\"24px\"}},\"linkDestination\":\"none\"} -->\n        <figure class=\"wp-block-image size-full\" style=\"border-radius:24px\">\n          <!-- Terapeuta homem sorrindo naturalmente, sessão presencial sem máscara -->\n          <!-- tons neutros/quentes, expressão aberta e acolhedora -->\n          <img src=\"https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?w=700&q=88&fit=crop&crop=top\" alt=\"Terapeuta profissional sorrindo, sessão de atendimento acolhedora\" style=\"width:100%;height:520px;object-fit:cover;object-position:50% 15%;border-radius:24px\"/>\n        </figure>\n        <!-- /wp:image -->\n\n      </div>\n      <!-- /wp:column -->\n\n      <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"54%\"} -->\n      <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:54%\">\n\n        <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#E03673\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.73rem\",\"letterSpacing\":\"3px\",\"textTransform\":\"uppercase\"}}} -->\n        <p class=\"has-text-color\" style=\"color:#E03673;font-weight:700;font-size:0.73rem;letter-spacing:3px;text-transform:uppercase\">Sobre o Meu Divã</p>\n        <!-- /wp:paragraph -->\n\n        <!-- wp:heading {\"level\":2,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontSize\":\"clamp(1.8rem,2.8vw,2.2rem)\",\"fontWeight\":\"800\",\"lineHeight\":\"1.2\"}}} -->\n        <h2 class=\"wp-block-heading has-text-color\" style=\"color:#1a1a2e;font-size:clamp(1.8rem,2.8vw,2.2rem);font-weight:800;line-height:1.2\">Um espaço que respeita seu tempo, sua história e seu jeito de ser.</h2>\n        <!-- /wp:heading -->\n\n        <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#666\"},\"typography\":{\"fontSize\":\"1rem\",\"lineHeight\":\"1.78\"}}} -->\n        <p class=\"has-text-color\" style=\"color:#666;font-size:1rem;line-height:1.78\">O Meu Divã nasceu para tornar a terapia acessível, acolhedora e sem burocracia. Conectamos pacientes a terapeutas qualificados em uma plataforma segura, com foco no que realmente importa: o cuidado.</p>\n        <!-- /wp:paragraph -->\n\n        <!-- wp:list {\"style\":{\"spacing\":{\"padding\":{\"left\":\"0\"}}},\"className\":\"is-style-none\"} -->\n        <ul class=\"wp-block-list is-style-none\" style=\"padding-left:0;list-style:none\">\n          <!-- wp:list-item {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"10px\"}}}} -->\n          <li style=\"margin-bottom:10px\">✅ &nbsp;<strong>Terapeutas verificados</strong> — formação e registro validados</li>\n          <!-- /wp:list-item -->\n          <!-- wp:list-item {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"10px\"}}}} -->\n          <li style=\"margin-bottom:10px\">🔒 &nbsp;<strong>Sigilo total</strong> — suas sessões são protegidas e confidenciais</li>\n          <!-- /wp:list-item -->\n          <!-- wp:list-item {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"10px\"}}}} -->\n          <li style=\"margin-bottom:10px\">📋 &nbsp;<strong>Prontuário digital</strong> — histórico organizado a cada sessão</li>\n          <!-- /wp:list-item -->\n          <!-- wp:list-item {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"10px\"}}}} -->\n          <li style=\"margin-bottom:10px\">🗓 &nbsp;<strong>Flexibilidade total</strong> — agende, cancele ou reagende sem burocracia</li>\n          <!-- /wp:list-item -->\n          <!-- wp:list-item -->\n          <li>💻 &nbsp;<strong>100% online</strong> — de qualquer lugar, no seu ritmo</li>\n          <!-- /wp:list-item -->\n        </ul>\n        <!-- /wp:list -->\n\n        <!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"32px\"}}}} -->\n        <div class=\"wp-block-buttons\" style=\"margin-top:32px\">\n          <!-- wp:button {\"style\":{\"color\":{\"background\":\"#E03673\",\"text\":\"#ffffff\"},\"border\":{\"radius\":\"50px\"},\"spacing\":{\"padding\":{\"top\":\"14px\",\"bottom\":\"14px\",\"left\":\"30px\",\"right\":\"30px\"}},\"typography\":{\"fontWeight\":\"700\"}}} -->\n          <div class=\"wp-block-button\"><a class=\"wp-block-button__link has-background wp-element-button\" href=\"/busca\" style=\"background-color:#E03673;color:#ffffff;border-radius:50px;padding:14px 30px;font-weight:700\">Conhecer os terapeutas →</a></div>\n          <!-- /wp:button -->\n        </div>\n        <!-- /wp:buttons -->\n\n      </div>\n      <!-- /wp:column -->\n\n    </div>\n    <!-- /wp:columns -->\n\n  </div>\n  <!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n\n<!-- ═══════════════════════════════════════════════════════════\n     PARA QUEM É — 3 CARDS\n════════════════════════════════════════════════════════════ -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"color\":{\"background\":\"#F4F8FF\"},\"spacing\":{\"padding\":{\"top\":\"88px\",\"bottom\":\"88px\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#F4F8FF;margin-top:0;margin-bottom:0;padding-top:88px;padding-bottom:88px\">\n\n  <!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1100px\"}} -->\n  <div class=\"wp-block-group\">\n\n    <!-- wp:paragraph {\"align\":\"center\",\"style\":{\"color\":{\"text\":\"#E03673\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.73rem\",\"letterSpacing\":\"3px\",\"textTransform\":\"uppercase\"}}} -->\n    <p class=\"has-text-align-center has-text-color\" style=\"color:#E03673;font-weight:700;font-size:0.73rem;letter-spacing:3px;text-transform:uppercase\">Um espaço para todos</p>\n    <!-- /wp:paragraph -->\n\n    <!-- wp:heading {\"textAlign\":\"center\",\"level\":2,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontSize\":\"clamp(1.8rem,3vw,2.2rem)\",\"fontWeight\":\"800\"},\"spacing\":{\"margin\":{\"bottom\":\"56px\"}}}} -->\n    <h2 class=\"wp-block-heading has-text-align-center has-text-color\" style=\"color:#1a1a2e;font-size:clamp(1.8rem,3vw,2.2rem);font-weight:800;margin-bottom:56px\">Um espaço para diferentes caminhos</h2>\n    <!-- /wp:heading -->\n\n    <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"22px\"}}}} -->\n    <div class=\"wp-block-columns alignwide\">\n\n      <!-- CARD: Para você — mulher com fone acenando para notebook, igual ao 19.png -->\n      <!-- wp:column {\"style\":{\"color\":{\"background\":\"#ffffff\"},\"border\":{\"radius\":\"24px\"},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n      <div class=\"wp-block-column has-background\" style=\"background-color:#ffffff;border-radius:24px;overflow:hidden\">\n        <!-- wp:image {\"sizeSlug\":\"full\",\"style\":{\"border\":{\"radius\":\"0\"}},\"linkDestination\":\"none\"} -->\n        <figure class=\"wp-block-image size-full\" style=\"margin:0\">\n          <!-- Mulher jovem com fone, notebook, acenando — sessão online real, tons quentes -->\n          <img src=\"https://images.unsplash.com/photo-1543269865-cbf427effbad?w=600&q=88&fit=crop\" alt=\"Paciente em sessão de terapia online, expressão de abertura e alegria\" style=\"width:100%;height:230px;object-fit:cover;object-position:50% 25%\"/>\n        </figure>\n        <!-- /wp:image -->\n        <!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"28px\",\"bottom\":\"34px\",\"left\":\"28px\",\"right\":\"28px\"}}}} -->\n        <div class=\"wp-block-group\" style=\"padding:28px 28px 34px\">\n          <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#E03673\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.70rem\",\"letterSpacing\":\"2.5px\",\"textTransform\":\"uppercase\"}}} -->\n          <p class=\"has-text-color\" style=\"color:#E03673;font-weight:700;font-size:0.70rem;letter-spacing:2.5px;text-transform:uppercase\">Para você</p>\n          <!-- /wp:paragraph -->\n          <!-- wp:heading {\"level\":3,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontSize\":\"1.15rem\",\"fontWeight\":\"700\"}}} -->\n          <h3 class=\"wp-block-heading has-text-color\" style=\"color:#1a1a2e;font-size:1.15rem;font-weight:700\">Cuidado emocional no seu ritmo</h3>\n          <!-- /wp:heading -->\n          <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#666\"},\"typography\":{\"fontSize\":\"0.90rem\",\"lineHeight\":\"1.68\"}}} -->\n          <p class=\"has-text-color\" style=\"color:#666;font-size:0.90rem;line-height:1.68\">Liberdade para escolher seu terapeuta, seu horário e construir seu processo com autonomia.</p>\n          <!-- /wp:paragraph -->\n          <!-- wp:buttons -->\n          <div class=\"wp-block-buttons\">\n            <!-- wp:button {\"style\":{\"color\":{\"background\":\"#E03673\",\"text\":\"#ffffff\"},\"border\":{\"radius\":\"50px\"},\"spacing\":{\"padding\":{\"top\":\"10px\",\"bottom\":\"10px\",\"left\":\"22px\",\"right\":\"22px\"}},\"typography\":{\"fontSize\":\"0.84rem\",\"fontWeight\":\"600\"}}} -->\n            <div class=\"wp-block-button\"><a class=\"wp-block-button__link has-background wp-element-button\" href=\"/para-voce\" style=\"background-color:#E03673;color:#ffffff;border-radius:50px;padding:10px 22px;font-size:0.84rem;font-weight:600\">Saiba mais →</a></div>\n            <!-- /wp:button -->\n          </div>\n          <!-- /wp:buttons -->\n        </div>\n        <!-- /wp:group -->\n      </div>\n      <!-- /wp:column -->\n\n      <!-- CARD: Para terapeutas — profissional confiante -->\n      <!-- wp:column {\"style\":{\"color\":{\"background\":\"#ffffff\"},\"border\":{\"radius\":\"24px\"},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n      <div class=\"wp-block-column has-background\" style=\"background-color:#ffffff;border-radius:24px;overflow:hidden\">\n        <!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n        <figure class=\"wp-block-image size-full\" style=\"margin:0\">\n          <!-- Terapeuta mulher, sorrindo, profissional, sem máscara, luz natural -->\n          <img src=\"https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=600&q=88&fit=crop\" alt=\"Terapeuta profissional confiante e acolhedora\" style=\"width:100%;height:230px;object-fit:cover;object-position:50% 20%\"/>\n        </figure>\n        <!-- /wp:image -->\n        <!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"28px\",\"bottom\":\"34px\",\"left\":\"28px\",\"right\":\"28px\"}}}} -->\n        <div class=\"wp-block-group\" style=\"padding:28px 28px 34px\">\n          <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#2F80D3\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.70rem\",\"letterSpacing\":\"2.5px\",\"textTransform\":\"uppercase\"}}} -->\n          <p class=\"has-text-color\" style=\"color:#2F80D3;font-weight:700;font-size:0.70rem;letter-spacing:2.5px;text-transform:uppercase\">Para terapeutas</p>\n          <!-- /wp:paragraph -->\n          <!-- wp:heading {\"level\":3,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontSize\":\"1.15rem\",\"fontWeight\":\"700\"}}} -->\n          <h3 class=\"wp-block-heading has-text-color\" style=\"color:#1a1a2e;font-size:1.15rem;font-weight:700\">Construa sua prática com autonomia</h3>\n          <!-- /wp:heading -->\n          <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#666\"},\"typography\":{\"fontSize\":\"0.90rem\",\"lineHeight\":\"1.68\"}}} -->\n          <p class=\"has-text-color\" style=\"color:#666;font-size:0.90rem;line-height:1.68\">Agenda, prontuário e gestão financeira integrados. Foque no que importa — seu paciente.</p>\n          <!-- /wp:paragraph -->\n          <!-- wp:buttons -->\n          <div class=\"wp-block-buttons\">\n            <!-- wp:button {\"style\":{\"color\":{\"background\":\"#2F80D3\",\"text\":\"#ffffff\"},\"border\":{\"radius\":\"50px\"},\"spacing\":{\"padding\":{\"top\":\"10px\",\"bottom\":\"10px\",\"left\":\"22px\",\"right\":\"22px\"}},\"typography\":{\"fontSize\":\"0.84rem\",\"fontWeight\":\"600\"}}} -->\n            <div class=\"wp-block-button\"><a class=\"wp-block-button__link has-background wp-element-button\" href=\"/para-terapeutas\" style=\"background-color:#2F80D3;color:#ffffff;border-radius:50px;padding:10px 22px;font-size:0.84rem;font-weight:600\">Saiba mais →</a></div>\n            <!-- /wp:button -->\n          </div>\n          <!-- /wp:buttons -->\n        </div>\n        <!-- /wp:group -->\n      </div>\n      <!-- /wp:column -->\n\n      <!-- CARD: Para empresas -->\n      <!-- wp:column {\"style\":{\"color\":{\"background\":\"#ffffff\"},\"border\":{\"radius\":\"24px\"},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n      <div class=\"wp-block-column has-background\" style=\"background-color:#ffffff;border-radius:24px;overflow:hidden\">\n        <!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n        <figure class=\"wp-block-image size-full\" style=\"margin:0\">\n          <!-- Equipe diversa sorrindo, reunião descontraída, ambiente humano -->\n          <img src=\"https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=600&q=88&fit=crop\" alt=\"Equipe diversa em ambiente de trabalho saudável e descontraído\" style=\"width:100%;height:230px;object-fit:cover;object-position:50% 30%\"/>\n        </figure>\n        <!-- /wp:image -->\n        <!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"28px\",\"bottom\":\"34px\",\"left\":\"28px\",\"right\":\"28px\"}}}} -->\n        <div class=\"wp-block-group\" style=\"padding:28px 28px 34px\">\n          <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#E03673\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.70rem\",\"letterSpacing\":\"2.5px\",\"textTransform\":\"uppercase\"}}} -->\n          <p class=\"has-text-color\" style=\"color:#E03673;font-weight:700;font-size:0.70rem;letter-spacing:2.5px;text-transform:uppercase\">Para empresas</p>\n          <!-- /wp:paragraph -->\n          <!-- wp:heading {\"level\":3,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontSize\":\"1.15rem\",\"fontWeight\":\"700\"}}} -->\n          <h3 class=\"wp-block-heading has-text-color\" style=\"color:#1a1a2e;font-size:1.15rem;font-weight:700\">Saúde emocional como estratégia</h3>\n          <!-- /wp:heading -->\n          <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#666\"},\"typography\":{\"fontSize\":\"0.90rem\",\"lineHeight\":\"1.68\"}}} -->\n          <p class=\"has-text-color\" style=\"color:#666;font-size:0.90rem;line-height:1.68\">Reduza afastamentos, aumente engajamento e construa uma cultura de cuidado real.</p>\n          <!-- /wp:paragraph -->\n          <!-- wp:buttons -->\n          <div class=\"wp-block-buttons\">\n            <!-- wp:button {\"style\":{\"color\":{\"background\":\"#E03673\",\"text\":\"#ffffff\"},\"border\":{\"radius\":\"50px\"},\"spacing\":{\"padding\":{\"top\":\"10px\",\"bottom\":\"10px\",\"left\":\"22px\",\"right\":\"22px\"}},\"typography\":{\"fontSize\":\"0.84rem\",\"fontWeight\":\"600\"}}} -->\n            <div class=\"wp-block-button\"><a class=\"wp-block-button__link has-background wp-element-button\" href=\"/empresas\" style=\"background-color:#E03673;color:#ffffff;border-radius:50px;padding:10px 22px;font-size:0.84rem;font-weight:600\">Saiba mais →</a></div>\n            <!-- /wp:button -->\n          </div>\n          <!-- /wp:buttons -->\n        </div>\n        <!-- /wp:group -->\n      </div>\n      <!-- /wp:column -->\n\n    </div>\n    <!-- /wp:columns -->\n\n  </div>\n  <!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n\n<!-- ═══════════════════════════════════════════════════════════\n     DEPOIMENTOS\n     Foto lateral: mulher rindo espontaneamente, foto jornalística\n     não pose de stock — expressão genuína, luz natural\n════════════════════════════════════════════════════════════ -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"white\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"96px\",\"bottom\":\"96px\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-group alignfull has-white-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:96px;padding-bottom:96px\">\n\n  <!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1100px\"}} -->\n  <div class=\"wp-block-group\">\n\n    <!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"80px\"}}}} -->\n    <div class=\"wp-block-columns alignwide\">\n\n      <!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"52%\"} -->\n      <div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:52%\">\n\n        <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#E03673\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.73rem\",\"letterSpacing\":\"3px\",\"textTransform\":\"uppercase\"}}} -->\n        <p class=\"has-text-color\" style=\"color:#E03673;font-weight:700;font-size:0.73rem;letter-spacing:3px;text-transform:uppercase\">Depoimentos</p>\n        <!-- /wp:paragraph -->\n\n        <!-- wp:heading {\"level\":2,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontSize\":\"clamp(1.8rem,2.8vw,2.2rem)\",\"fontWeight\":\"800\",\"lineHeight\":\"1.2\"},\"spacing\":{\"margin\":{\"bottom\":\"40px\"}}}} -->\n        <h2 class=\"wp-block-heading has-text-color\" style=\"color:#1a1a2e;font-size:clamp(1.8rem,2.8vw,2.2rem);font-weight:800;line-height:1.2;margin-bottom:40px\">Quem começa, continua.</h2>\n        <!-- /wp:heading -->\n\n        <!-- Depoimento 1 -->\n        <!-- wp:group {\"style\":{\"color\":{\"background\":\"#F9F5FF\"},\"border\":{\"radius\":\"20px\",\"left\":{\"color\":\"#E03673\",\"width\":\"4px\"}},\"spacing\":{\"padding\":{\"top\":\"26px\",\"bottom\":\"26px\",\"left\":\"28px\",\"right\":\"28px\"},\"margin\":{\"bottom\":\"16px\"}}}} -->\n        <div class=\"wp-block-group has-background\" style=\"background-color:#F9F5FF;border-radius:20px;border-left:4px solid #E03673;padding:26px 28px;margin-bottom:16px\">\n          <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#333\"},\"typography\":{\"fontSize\":\"0.97rem\",\"lineHeight\":\"1.78\",\"fontStyle\":\"italic\"}}} -->\n          <p class=\"has-text-color\" style=\"color:#333;font-size:0.97rem;line-height:1.78;font-style:italic\">\"Finalmente encontrei um terapeuta que entende minhas necessidades. A plataforma é simples, acolhedora e o atendimento excepcional. Mudou minha relação comigo mesma.\"</p>\n          <!-- /wp:paragraph -->\n          <!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"12px\"},\"margin\":{\"top\":\"20px\"}}}} -->\n          <div class=\"wp-block-columns\" style=\"margin-top:20px\">\n            <!-- wp:column {\"width\":\"44px\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n            <div class=\"wp-block-column\" style=\"flex-basis:44px\">\n              <!-- wp:image {\"width\":44,\"height\":44,\"sizeSlug\":\"thumbnail\",\"style\":{\"border\":{\"radius\":\"50%\"}}} -->\n              <figure class=\"wp-block-image size-thumbnail is-resized\" style=\"border-radius:50%;overflow:hidden\">\n                <img src=\"https://images.unsplash.com/photo-1531123897727-8f129e1688ce?w=88&q=88&fit=crop&crop=faces\" alt=\"Ana M.\" width=\"44\" height=\"44\" style=\"object-fit:cover;object-position:50% 10%\"/>\n              </figure>\n              <!-- /wp:image -->\n            </div>\n            <!-- /wp:column -->\n            <!-- wp:column {\"verticalAlignment\":\"center\"} -->\n            <div class=\"wp-block-column is-vertically-aligned-center\">\n              <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.88rem\"},\"spacing\":{\"margin\":{\"bottom\":\"2px\"}}}} -->\n              <p class=\"has-text-color\" style=\"color:#1a1a2e;font-weight:700;font-size:0.88rem;margin-bottom:2px\">Ana M.</p>\n              <!-- /wp:paragraph -->\n              <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#999\"},\"typography\":{\"fontSize\":\"0.77rem\"}}} -->\n              <p class=\"has-text-color\" style=\"color:#999;font-size:0.77rem\">São Paulo, SP &nbsp;·&nbsp; ⭐⭐⭐⭐⭐</p>\n              <!-- /wp:paragraph -->\n            </div>\n            <!-- /wp:column -->\n          </div>\n          <!-- /wp:columns -->\n        </div>\n        <!-- /wp:group -->\n\n        <!-- Depoimento 2 -->\n        <!-- wp:group {\"style\":{\"color\":{\"background\":\"#EBF4FF\"},\"border\":{\"radius\":\"20px\",\"left\":{\"color\":\"#2F80D3\",\"width\":\"4px\"}},\"spacing\":{\"padding\":{\"top\":\"26px\",\"bottom\":\"26px\",\"left\":\"28px\",\"right\":\"28px\"}}}} -->\n        <div class=\"wp-block-group has-background\" style=\"background-color:#EBF4FF;border-radius:20px;border-left:4px solid #2F80D3;padding:26px 28px\">\n          <!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#333\"},\"typography\":{\"fontSize\":\"0.97rem\",\"lineHeight\":\"1.78\",\"fontStyle\":\"italic\"}}} -->\n          <p class=\"has-text-color\" style=\"color:#333;font-size:0.97rem;line-height:1.78;font-style:italic\">\"O processo foi simples desde o início. Encontrei minha terape