renciais\n════════════════════════════════════════════════════════════ -->\n\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"white\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"96px\",\"bottom\":\"96px\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-group alignfull has-white-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:96px;padding-bottom:96px\">\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1100px\"}} -->\n<div class=\"wp-block-group\">\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"80px\"}}}} -->\n<div class=\"wp-block-columns alignwide\">\n\n<!-- wp:column {\"width\":\"46%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:46%\">\n<!-- wp:image {\"sizeSlug\":\"full\",\"style\":{\"border\":{\"radius\":\"24px\"}},\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\" style=\"border-radius:24px;overflow:hidden\">\n<img src=\"https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?w=700&q=88&fit=crop&crop=top\" alt=\"Terapeuta profissional sorrindo, sessão de atendimento acolhedora\" style=\"width:100%;height:520px;object-fit:cover;object-position:50% 15%;border-radius:24px\"/>\n</figure>\n<!-- /wp:image -->\n</div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"54%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:54%\">\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#E03673\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.73rem\",\"letterSpacing\":\"3px\",\"textTransform\":\"uppercase\"}}} -->\n<p class=\"has-text-color\" style=\"color:#E03673;font-weight:700;font-size:0.73rem;letter-spacing:3px;text-transform:uppercase\">Sobre o Meu Divã</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontSize\":\"clamp(1.8rem,2.8vw,2.2re