:paragraph -->\r\n<!-- wp:buttons -->\r\n<div class=\"wp-block-buttons\">\r\n<!-- wp:button {\"style\":{\"color\":{\"background\":\"#E03673\",\"text\":\"#ffffff\"},\"border\":{\"radius\":\"50px\"},\"spacing\":{\"padding\":{\"top\":\"10px\",\"bottom\":\"10px\",\"left\":\"22px\",\"right\":\"22px\"}},\"typography\":{\"fontSize\":\"0.84rem\",\"fontWeight\":\"600\"}}} -->\r\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-background wp-element-button\" href=\"/empresas\" style=\"background-color:#E03673;color:#ffffff;border-radius:50px;padding:10px 22px;font-size:0.84rem;font-weight:600\">Saiba mais →</a></div>\r\n<!-- /wp:button -->\r\n</div>\r\n<!-- /wp:buttons -->\r\n</div>\r\n<!-- /wp:group -->\r\n</div>\r\n<!-- /wp:column -->\r\n\r\n</div>\r\n<!-- /wp:columns -->\r\n\r\n</div>\r\n<!-- /wp:group -->\r\n\r\n</div>\r\n<!-- /wp:group -->\r\n\r\n\r\n<!-- ═══════════════════════════════════════════════════════════\r\n     DEPOIMENTOS — foto espontânea, não pose de stock\r\n════════════════════════════════════════════════════════════ -->\r\n\r\n<!-- wp:group {\"align\":\"full\",\"backgroundColor\":\"white\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"96px\",\"bottom\":\"96px\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\r\n<div class=\"wp-block-group alignfull has-white-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:96px;padding-bottom:96px\">\r\n\r\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1100px\"}} -->\r\n<div class=\"wp-block-group\">\r\n\r\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"80px\"}}}} -->\r\n<div class=\"wp-block-columns alignwide\">\r\n\r\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"52%\"} -->\r\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:52%\">\r\n\r\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#E03673\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.73rem\",\"letterSpacing\":\"3px\",\"textTransform\":\"uppercase\"}}} -->\r\n<p class=\"has-text-color\" style=\"color:#E03673;font-weight:700;font-size:0.73rem;letter-spacing:3px;text-transform:uppercase\">Depoimentos</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:heading {\"level\":2,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontSize\":\"clamp(1.8rem,2.8vw,2.2rem)\",\"fontWeight\":\"800\",\"lineHeight\":\"1.2\"},\"spacing\":{\"margin\":{\"bottom\":\"40px\"}}}} -->\r\n<h2 class=\"wp-block-heading has-text-color\" style=\"color:#1a1a2e;font-size:clamp(1.8rem,2.8vw,2.2rem);font-weight:800;line-height:1.2;margin-bottom:40px\">Quem começa, continua.</h2>\r\n<!-- /wp:heading -->\r\n\r\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#F9F5FF\"},\"border\":{\"radius\":\"20px\",\"left\":{\"color\":\"#E03673\",\"width\":\"4px\"}},\"spacing\":{\"padding\":{\"top\":\"26px\",\"bottom\":\"26px\",\"left\":\"28px\",\"right\":\"28px\"},\"margin\":{\"bottom\":\"16px\"}}}} -->\r\n<div class=\"wp-block-group has-background\" style=\"background-color:#F9F5FF;border-radius:20px;border-left:4px solid #E03673;padding:26px 28px;margin-bottom:16px\">\r\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#333\"},\"typography\":{\"fontSize\":\"0.97rem\",\"lineHeight\":\"1.78\",\"fontStyle\":\"italic\"}}} -->\r\n<p class=\"has-text-color\" style=\"color:#333;font-size:0.97rem;line-height:1.78;font-style:italic\">\"Finalmente encontrei um terapeuta que entende minhas necessidades. A plataforma é simples, acolhedora e o atendimento excepcional. Mudou minha relação comigo mesma.\"</p>\r\n<!-- /wp:paragraph -->\r\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"12px\"},\"margin\":{\"top\":\"20px\"}}}} -->\r\n<div class=\"wp-block-columns\" style=\"margin-top:20px\">\r\n<!-- wp:column {\"width\":\"52px\"} -->\r\n<div class=\"wp-block-column\" style=\"flex-basis:52px\">\r\n<!-- wp:image {\"width\":44,\"height\":44,\"sizeSlug\":\"thumbnail\",\"style\":{\"border\":{\"radius\":\"50%\"}},\"linkDestination\":\"none\"} -->\r\n<figure class=\"wp-block-image size-thumbnail is-resized\" style=\"border-radius:50%;overflow:hidden\"><img src=\"https://images.unsplash.com/photo-1531123897727-8f129e1688ce?w=88&q=88&fit=crop&crop=faces\" alt=\"Ana M.\" width=\"44\" height=\"44\" style=\"object-fit:cover;object-position:50% 10%\"/></figure>\r\n<!-- /wp:image -->\r\n</div>\r\n<!-- /wp:column -->\r\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\r\n<div class=\"wp-block-column is-vertically-aligned-center\">\r\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.88rem\"},\"spacing\":{\"margin\":{\"bottom\":\"2px\"}}}} -->\r\n<p class=\"has-text-color\" style=\"color:#1a1a2e;font-weight:700;font-size:0.88rem;margin-bottom:2px\">Ana M.</p>\r\n<!-- /wp:paragraph -->\r\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#999\"},\"typography\":{\"fontSize\":\"0.77rem\"},\"spacing\":{\"margin\":{\"top\":\"0\"}}}} -->\r\n<p class=\"has-text-color\" style=\"color:#999;font-size:0.77rem;margin-top:0\">São Paulo, SP &nbsp;·&nbsp; ⭐⭐⭐⭐⭐</p>\r\n<!-- /wp:paragraph -->\r\n</div>\r\n<!-- /wp:column -->\r\n</div>\r\n<!-- /wp:columns -->\r\n</div>\r\n<!-- /wp:group -->\r\n\r\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#EBF4FF\"},\"border\":{\"radius\":\"20px\",\"left\":{\"color\":\"#2F80D3\",\"width\":\"4px\"}},\"spacing\":{\"padding\":{\"top\":\"26px\",\"bottom\":\"26px\",\"left\":\"28px\",\"right\":\"28px\"}}}} -->\r\n<div class=\"wp-block-group has-background\" style=\"background-color:#EBF4FF;border-radius:20px;border-left:4px solid #2F80D3;padding:26px 28px\">\r\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#333\"},\"typography\":{\"fontSize\":\"0.97rem\",\"lineHeight\":\"1.78\",\"fontStyle\":\"italic\"}}} -->\r\n<p class=\"has-text-color\" style=\"color:#333;font-size:0.97rem;line-height:1.78;font-style:italic\">\"O processo foi simples desde o início. Encontrei minha terapeuta em minutos e a sessão aconteceu no mesmo dia. Recomendo para todo mundo que está pensando em começar.\"</p>\r\n<!-- /wp:paragraph -->\r\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"12px\"},\"margin\":{\"top\":\"20px\"}}}} -->\r\n<div class=\"wp-block-columns\" style=\"margin-top:20px\">\r\n<!-- wp:column {\"width\":\"52px\"} -->\r\n<div class=\"wp-block-column\" style=\"flex-basis:52px\">\r\n<!-- wp:image {\"width\":44,\"height\":44,\"sizeSlug\":\"thumbnail\",\"style\":{\"border\":{\"radius\":\"50%\"}},\"linkDestination\":\"none\"} -->\r\n<figure class=\"wp-block-image size-thumbnail is-resized\" style=\"border-radius:50%;overflow:hidden\"><img src=\"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=88&q=88&fit=crop&crop=faces\" alt=\"Carlos R.\" width=\"44\" height=\"44\" style=\"object-fit:cover;object-position:50% 10%\"/></figure>\r\n<!-- /wp:image -->\r\n</div>\r\n<!-- /wp:column -->\r\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\r\n<div class=\"wp-block-column is-vertically-aligned-center\">\r\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.88rem\"},\"spacing\":{\"margin\":{\"bottom\":\"2px\"}}}} -->\r\n<p class=\"has-text-color\" style=\"color:#1a1a2e;font-weight:700;font-size:0.88rem;margin-bottom:2px\">Carlos R.</p>\r\n<!-- /wp:paragraph -->\r\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#999\"},\"typography\":{\"fontSize\":\"0.77rem\"},\"spacing\":{\"margin\":{\"top\":\"0\"}}}} -->\r\n<p class=\"has-text-color\" style=\"color:#999;font-size:0.77rem;margin-top:0\">Belo Horizonte, MG &nbsp;·&nbsp; ⭐⭐⭐⭐⭐</p>\r\n<!-- /wp:paragraph -->\r\n</div>\r\n<!-- /wp:column -->\r\n</div>\r\n<!-- /wp:columns -->\r\n</div>\r\n<!-- /wp:group -->\r\n\r\n</div>\r\n<!-- /wp:column -->\r\n\r\n<!-- wp:column {\"width\":\"48%\"} -->\r\n<div class=\"wp-block-column\" style=\"flex-basis:48%\">\r\n<!-- wp:image {\"sizeSlug\":\"full\",\"st