n</div>\n<!-- /wp:buttons -->\n\n</div>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:column -->\n\n<!-- CASE 5 -->\n<!-- wp:column {\"style\":{\"color\":{\"background\":\"#ffffff\"},\"border\":{\"radius\":\"24px\"},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-column has-background\" style=\"background-color:#ffffff;border-radius:24px;overflow:hidden\">\n\n<!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<figure class=\"wp-block-image size-full\" style=\"margin:0\">\n<img src=\"https://images.unsplash.com/photo-1504384308090-c894fdcc538d?w=600&q=88&fit=crop\" alt=\"Indústria com foco em bem-estar e segurança psicológica\" style=\"width:100%;height:220px;object-fit:cover;object-position:50% 40%;display:block\"/>\n</figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"32px\",\"bottom\":\"36px\",\"left\":\"32px\",\"right\":\"32px\"}}}} -->\n<div class=\"wp-block-group\" style=\"padding:32px 32px 36px\">\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#EBF4FF\"},\"border\":{\"radius\":\"8px\"},\"spacing\":{\"padding\":{\"top\":\"5px\",\"bottom\":\"5px\",\"left\":\"12px\",\"right\":\"12px\"},\"margin\":{\"bottom\":\"16px\"}}}} -->\n<div class=\"wp-block-group has-background\" style=\"background-color:#EBF4FF;border-radius:8px;padding:5px 12px;margin-bottom:16px;display:inline-block\">\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#2F80D3\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.70rem\",\"letterSpacing\":\"1.5px\",\"textTransform\":\"uppercase\"}}} -->\n<p class=\"has-text-color\" style=\"color:#2F80D3;font-weight:700;font-size:0.70rem;letter-spacing:1.5px;text-transform:uppercase;margin:0\">Indústria · 480 colaboradores</p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fon