 alignwide\" style=\"margin-bottom:64px\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":99,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"20px\"}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\"><img src=\"https://meudivaonline.com/wp-content/uploads/2026/04/1.png\" alt=\"\" class=\"wp-image-99\" style=\"border-radius:20px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"20px\"}}}} -->\n<div class=\"wp-block-group\" style=\"margin-bottom:20px\"><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontWeight\":\"800\",\"fontSize\":\"1rem\"}}} -->\n<p class=\"has-text-color\" style=\"color:#ffffff;font-size:1rem;font-weight:800\"><p class=\"has-text-color\" style=\"background:#2F80D3;color:#ffffff;font-weight:800;font-size:1rem;width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0;flex-shrink:0\">02</p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#2F80D3\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.73rem\",\"letterSpacing\":\"2px\",\"textTransform\":\"uppercase\"}}} -->\n<p class=\"has-text-color\" style=\"color:#2F80D3;font-size:0.73rem;font-weight:700;letter-spacing:2px;text-transform:uppercase\"><p class=\"has-text-color\" style=\"color:#2F80D3;font-weight:700;font-size:0.73rem;letter-spacing:2px;text-transform:uppercase;margin:0\">Agende</p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"color\":{\"text\":\"#1a1a2e\"},\"typography\":{\"fontSize\":\"1.5rem\",\"fon