ct x=\'2\' y=\'3\' width=\'20\' height=\'14\' rx=\'2\' ry=\'2\'/%3E%3Cline x1=\'8\' y1=\'21\' x2=\'16\' y2=\'21\'/%3E%3Cline x1=\'12\' y1=\'17\' x2=\'12\' y2=\'21\'/%3E%3C/svg%3E\" alt=\"\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"4px\"}}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#ffffff\"},\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"0.97rem\"},\"spacing\":{\"margin\":{\"bottom\":\"2px\"}}}} -->\n<p class=\"has-text-color\" style=\"color:#ffffff;margin-bottom:2px;font-size:0.97rem;font-weight:700\">Plataforma segura e criptografada</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"rgba(255,255,255,0.65)\"},\"typography\":{\"fontSize\":\"0.84rem\"},\"spacing\":{\"margin\":{\"top\":\"0\"}}}} -->\n<p class=\"has-text-color\" style=\"color:rgba(255,255,255,0.65);margin-top:0;font-size:0.84rem\">Videochamadas via Google Meet com criptografia de ponta a ponta.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:cover {\"url\":\"https://meudivaonline.com/wp-content/uploads/2026/04/34-1024x576.png\",\"id\":74,\"isUserOverlayColor\":true,\"gradient\":\"accent-analogous\",\"contentPosition\":\"top center\",\"sizeSlug\":\"large\",\"align\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-cover alignfull has-custom-content-position is-position-top-center\" style=\"margin-top:0;margin-bottom:0\"><img class=\"wp-block-cover__image-background wp-image-74 size-large\" alt=\"\" src=\"https://meudivaonline.com/wp-content/uploads/2026/04/34-1024x576.png\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-100 has-background-dim wp-block-cover__gradient-background has-ba