INSERT INTO `wp_snippets` VALUES (1,'Tornar os nomes dos arquivos minúsculos no envio','Garante que imagens e arquivos enviados tenham nomes de arquivos em letras minúsculas.\n\nEste é um snippet de amostra. Sinta-se à vontade para usá-lo, editá-lo ou removê-lo.','add_filter( \'sanitize_file_name\', \'mb_strtolower\' );','sample, media','global',0,10,0,'2026-04-09 18:49:43',1,NULL),(2,'Desativar barra de administração','Desativa a barra de administração do WordPress para todos, exceto administradores.\n\nEste é um snippet de amostra. Sinta-se à vontade para usá-lo, editá-lo ou removê-lo.','add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );','sample, admin-bar','front-end',0,10,0,'2026-04-09 18:49:43',1,NULL),(3,'Permitir smilies','Permite a conversão de smiley em lugares obscuros.\n\nEste é um snippet de amostra. Sinta-se à vontade para usá-lo, editá-lo ou removê-lo.','add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );','sample','global',0,10,0,'2026-04-09 18:49:43',1,NULL),(4,'Ano atual','Shortcode para inserir o ano atual em um post ou uma página.\n\nEste é um snippet de amostra. Sinta-se à vontade para usá-lo, editá-lo ou removê-lo.','<?php echo date( \'Y\' ); ?>','sample, dates','content',0,10,0,'2026-04-09 18:49:43',1,NULL),(5,'Schema Meu Divã','','<!-- Schema: Organization -->\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Organization\",\n  \"name\": \"Meu Divã\",\n  \"legalName\": \"Instituto Superior de Psicanálise a Avia Ltda\",\n  \"alternateName\": \"Meu Diva Online\",\n  \"url\": \"https://meudivaonline.com\",\n  \"logo\": \"https://meudivaonline.com/wp-content/uploads/2026/04/Logo_Meu-Diva-2-edited.png\",\n  \"description\": \"Plataforma online de terapia que conecta pacientes a psicólogos, psicanalistas e terapeutas verificados. Agende sua sessão de qualquer lugar do Brasil.\",\n  \"foundingDate\": \"2024\",\n  \"areaServed\": \"BR\",\n  \"email\": \"contato@meudivaonline.com\",\n  \"telephone\": \"+553121812810\",\n  \"serviceType\": [\"Psicologia Online\", \"Psicanálise Online\", \"Terapia Online\", \"Saúde Mental\", \"Benefício Corporativo de Saúde Mental\"],\n  \"contactPoint\": {\n    \"@type\": \"ContactPoint\",\n    \"contactType\": \"customer support\",\n    \"email\": \"contato@meudivaonline.com\",\n    \"telephone\": \"+553121812810\",\n    \"availableLanguage\": \"Portuguese\"\n  },\n  \"sameAs\": [\n    \"https://instagram.com/meudiva.online\",\n    \"https://wa.me/553121812810\",\n    \"https://linkedin.com/company/meudiva\",\n    \"https://youtube.com/@meudivaonline\"\n  ]\n}\n</script>\n\n<!-- Schema: WebSite com SearchAction -->\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"WebSite\",\n  \"name\": \"Meu Divã\",\n  \"url\": \"https://meudivaonline.com\",\n  \"potentialAction\": {\n    \"@type\": \"SearchAction\",\n    \"target\": {\n      \"@type\": \"EntryPoint\",\n      \"urlTemplate\": \"https://app.meudivaonline.com/busca?q={search_term_string}\"\n    },\n    \"query-input\": \"required name=search_term_string\"\n  }\n}\n</script>\n\n<!-- Schema: Service -->\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Service\",\n  \"serviceType\": \"Terapia Online\",\n  \"provider\": {\n    \"@type\": \"Organization\",\n    \"name\": \"Meu Divã\",\n    \"url\": \"https://meudivaonline.com\"\n  },\n  \"name\": \"Terapia Online - Meu Divã\",\n  \"description\": \"Sessões de terapia online com psicólogos e psicanalistas verificados. Agende pelo site ou app, pague com cartão ou saldo na carteira digital.\",\n  \"areaServed\": {\n    \"@type\": \"Country\",\n    \"name\": \"Brasil\"\n  },\n  \"hasOfferCatalog\": {\n    \"@type\": \"OfferCatalog\",\n    \"name\": \"Planos Meu Divã\",\n    \"itemListElement\": [\n      {\n        \"@type\": \"Offer\",\n        \"itemOffered\": {\n          \"@type\": \"Service\",\n          \"name\": \"Sessão Individual\",\n          \"description\": \"Sessão de 50 minutos com psicólogo ou psicanalista verificado\"\n        }\n      },\n      {\n        \"@type\": \"Offer\",\n        \"itemOffered\": {\n          \"@type\": \"Service\",\n          \"name\": \"Plano Empresa\",\n          \"description\": \"Benefício corporativo de saúde mental para colaboradores\"\n        }\n      }\n    ]\n  }\n}\n</script>\n\n<!-- Schema: FAQPage -->\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"O que é o Meu Divã?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"O Meu Divã é uma plataforma online de terapia que conecta pacientes a psicólogos e psicanalistas verificados. Você pode agendar sessões de qualquer lugar do Brasil, pelo computador ou celular, com profissionais especializados em ansiedade, depressão, relacionamentos, autoconhecimento e muito mais.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Como funciona o Meu Divã?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"É simples: crie sua conta, escolha um terapeuta pelo nosso buscador com filtros de especialidade, abordagem e valor, adicione créditos na sua carteira digital e agende sua sessão. No dia marcado, acesse a videochamada direto pela plataforma, sem precisar instalar nada.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Quanto custa uma sessão no Meu Divã?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Os valores variam conforme o terapeuta escolhido. Cada profissional define seu próprio preço por sessão. Você pode ver o valor na página de perfil de cada terapeuta antes de agendar. O pagamento é feito via cartão de crédito ou saldo na carteira digital da plataforma.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Como escolher o terapeuta certo para mim?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"No Meu Divã você pode filtrar terapeutas por especialidade, abordagem terapêutica (psicanálise, TCC, etc.), gênero, idioma e valor por sessão. Cada perfil tem bio, formação, avaliações de outros pacientes e vídeo de apresentação, para você escolher com confiança.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"A terapia online é tão eficaz quanto a presencial?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Sim. Estudos científicos mostram que a terapia online tem eficácia equivalente à presencial para a maioria das condições. Além disso, oferece mais comodidade, privacidade e acessibilidade — você faz sua sessão de onde estiver, sem deslocamento.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Os terapeutas do Meu Divã são verificados?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Sim. Todos os profissionais passam por um processo de verificação de documentos, registro no conselho de classe (CRP para psicólogos) e validação de formação antes de aparecer na plataforma. Terapeutas verificados recebem um selo no perfil.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Posso cancelar ou reagendar uma sessão?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Sim. Você pode cancelar ou reagendar sua sessão com antecedência mínima de 24 horas sem custo. Cancelamentos com menos de 24 horas podem não ser reembolsados conforme a política do terapeuta.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Posso mudar de terapeuta se não estiver satisfeito?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Sim, absolutamente. Seu bem-estar é a prioridade. Você pode escolher outro profissional na plataforma a qualquer momento, sem burocracia.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"O Meu Divã tem plano para empresas?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Sim. Oferecemos planos corporativos de saúde mental para empresas que querem oferecer terapia como benefício para seus colaboradores. Os funcionários recebem créditos mensais para usar na plataforma com terapeutas de sua escolha.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Quais formas de pagamento são aceitas?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Aceitamos cartão de crédito e débito. Os valores são adicionados à sua carteira digital na plataforma e debitados automaticamente ao confirmar cada sessão.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"A plataforma é segura?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Sim. Todas as videochamadas são criptografadas, garantindo total sigilo entre você e seu terapeuta. Seus dados pessoais são protegidos conforme a LGPD (Lei Geral de Proteção de Dados).\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Sou terapeuta, como me cadastrar no Meu Divã?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Acesse meudivaonline.com, clique em Para Terapeutas e preencha o cadastro. Após validação dos documentos e aprovação, você já pode configurar sua agenda, definir seu valor por sessão e começar a atender pacientes pela plataforma.\"\n      }\n    }\n  ]\n}\n</script>','','head-content',0,10,1,'2026-04-25 00:50:39',1,NULL);
/*!40000 ALTER TABLE `wp_snippets` ENABLE KEYS */;
